sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.at-return{ border-radius:12px; background:#0b2233; color:#fff; margin:16px 0; }
.at-body{ display:flex; align-items:center; justify-content:space-between; gap:16px; padding:16px 20px; flex-wrap:wrap; }
.at-title{ font-weight:800; font-size:18px; margin-bottom:4px; display:flex; align-items:center; gap:8px; }
.at-meta{ opacity:.9; margin-bottom:6px; }
.at-label{ opacity:.85; margin-right:6px; }
.at-sep{ opacity:.6; margin:0 8px; }
.at-date{ font-size:16px; }

.at-badge{ display:inline-block; margin-left:10px; padding:2px 8px; border-radius:999px; font-weight:700; }
.at-badge.overdue{ background:#ff4d4f; color:#fff; }  /* red */
.at-badge.today{   background:#ffb020; color:#1b1b1b; }/* amber */
.at-badge.soon{    background:#2fbf71; color:#0b2233; }/* green */

.at-pill{ display:inline-block; padding:2px 8px; border-radius:999px; font-size:12px; font-weight:800; letter-spacing:.3px; }
.at-pill--overdue{ background:#ff4d4f; color:#fff; }
.at-pill--today{   background:#ffb020; color:#1b1b1b; }
.at-pill--soon{    background:#2fbf71; color:#0b2233; }

.at-actions .btn{ margin-left:8px; }
@media (max-width: 768px){
  .at-actions{ width:100%; display:flex; gap:8px; }
  .at-actions .btn{ flex:1 1 auto; margin:0; }
}

sp_widget.script:
(function () {
  // ====== CONFIG (adjust if your field names/values differ) ======
  var TRACKER_TABLE   = 'x_746154_loaner_0_vehicle_tracker';
  var USER_FIELD_1    = 'requested_for';      // first user field to check
  var USER_FIELD_2    = 'assigned_to';        // OR second user field
  var STATUS_FIELD    = 'vehicle_status';     // status field on tracker
  var OUT_VALUE       = 'out_on_field';       // stored value for “Out on Field”
  var RETURN_FIELD    = 'expected_return_date'; // date/datetime field name

  // Instance options (optional): threshold days, reschedule item, and var name to prefill
  var thresholdDays   = parseInt(options.threshold_days || 3, 10); // warn if due in ≤ N days
  var rescheduleItem  = options.reschedule_item_sys_id || '';      // catalog item sys_id
  var trackerVarName  = options.tracker_var_name || 'tracker';     // var name on that item

  data.show = false;
  data.hasTracker = false;
  data.reschedule_url = '';
  data.tracker_url = '';
  data.state = '';          // 'overdue' | 'today' | 'soon' | 'ok'
  data.days_left = null;
  data.return_display = '';
  data.vehicle = '';
  data.tracker_number = '';

  var me = gs.getUserID();

  var gr = new GlideRecord(TRACKER_TABLE);
  // current user's active tracker “out on field”
  var qc = gr.addQuery(USER_FIELD_1, me);
  qc.addOrCondition(USER_FIELD_2, me);
  gr.addQuery(STATUS_FIELD, OUT_VALUE);
  gr.addNotNullQuery(RETURN_FIELD);
  gr.orderBy('' + RETURN_FIELD);
  gr.setLimit(1);
  gr.query();

  if (gr.next()) {
    data.hasTracker     = true;
    data.tracker_sys_id = gr.getUniqueValue();
    data.tracker_number = gr.getDisplayValue('number') || gr.getValue('number');
    data.vehicle        = gr.getDisplayValue('vehicle');
    data.return_display = gr.getDisplayValue(RETURN_FIELD);

    // days left (integer, negative if overdue)
    var due = new GlideDateTime(gr.getValue(RETURN_FIELD));
    var now = new GlideDateTime();
    var diffMs = (due.getNumericValue() - now.getNumericValue());  // ms
    var oneDay = 1000 * 60 * 60 * 24;
    data.days_left = Math.floor(diffMs / oneDay);

    // state
    if (data.days_left < 0)        data.state = 'overdue';
    else if (data.days_left === 0) data.state = 'today';
    else if (data.days_left <= thresholdDays) data.state = 'soon';
    else                           data.state = 'ok';

    // show card only for overdue/today/soon (you can change this)
    data.show = (data.state !== 'ok');

    // links
    data.tracker_url = '/sp?id=form&table=' + TRACKER_TABLE + '&sys_id=' + data.tracker_sys_id;

    if (rescheduleItem) {
      // Deep-link to reschedule item, optionally prefill the tracker variable
      data.reschedule_url = '/sp?id=sc_cat_item&sys_id=' + rescheduleItem;
      if (trackerVarName) {
        data.reschedule_url += '&variables.' + trackerVarName + '=' + data.tracker_sys_id;
      }
    }
  }
})();
